const { chromium } = require('playwright-core');
const assert = require('node:assert/strict');
const fs=require('node:fs/promises');
const os=require('node:os');
const path=require('node:path');
const {makeSave} = require('./fixtures.cjs');
const base=process.argv[2]||'http://127.0.0.1:8765';
const team={id:'v76-test',name:'Regression Team',game:'Black',pokemon:Array(6).fill(null)};
const save=(level=38,version=21)=>({name:'party.sav',mimeType:'application/octet-stream',buffer:makeSave(version,level,level)});
(async()=>{
 const browser=await chromium.launch({executablePath:process.env.CHROMIUM_PATH||'/usr/bin/chromium',args:['--no-sandbox']});
 const context=await browser.newContext({viewport:{width:412,height:860},isMobile:true,hasTouch:true,reducedMotion:'reduce'});
 const temp=await fs.mkdtemp(path.join(os.tmpdir(),'takdex-saves-'));
 const selectedFile=path.join(temp,'party.sav');
 try{
  await context.addInitScript(t=>{
   if(localStorage.getItem('v76-test-loaded'))return;
   localStorage.setItem('v76-test-loaded','1');
   localStorage.setItem('poketact-teams',JSON.stringify([t]));
   localStorage.setItem('takdex-v71-active-team',t.id);
  },team);
  const page=await context.newPage();
  page.setDefaultTimeout(10000);
  const errors=[];
  page.on('pageerror',e=>{errors.push(e.message);console.error(e.stack);});
  await page.goto(base,{waitUntil:'domcontentloaded'});
  const picker=page.locator('[data-save-file]');
  const writeSnapshot=async bytes=>{
   await fs.writeFile(selectedFile,bytes);
   await fs.utimes(selectedFile,1700000000,1700000000);
  };
  await writeSnapshot(save().buffer);
  await picker.setInputFiles(selectedFile);
  await page.waitForFunction(()=>JSON.parse(localStorage.getItem('poketact-teams'))[0].pokemon[0]?.saveStats?.level===38);
  assert.match(await page.locator('[data-save-status]').textContent(),/Saved-game snapshot/);
  const stored=()=>page.evaluate(()=>JSON.parse(localStorage.getItem('poketact-teams'))[0]);
  const latest=await stored();
  assert.equal(latest.pokemon[0].id,10016);
  assert.equal(latest.pokemon[0].saveStats.currentHP,29);
  assert.equal(latest.pokemon[0].moves[0].remainingPP,9);
  const noChange=await page.evaluate(async data=>window.takDexSaveSync.synchronize({teamId:'v76-test',bytes:Uint8Array.from(atob(data),c=>c.charCodeAt(0))}),makeSave(21,38,38).toString('base64'));
  assert.equal(noChange,'unchanged');
  const stale=await page.evaluate(async data=>takDexSaveSync.synchronize({teamId:'v76-test',bytes:Uint8Array.from(atob(data),c=>c.charCodeAt(0))}),makeSave(21,37,37).toString('base64'));
  assert.equal(stale,'stale');
  await picker.setInputFiles(save(42,22));
  await page.waitForFunction(()=>document.querySelector('[data-save-status]').textContent.includes('White 2'));
  await picker.setInputFiles({name:'broken.sav',mimeType:'application/octet-stream',buffer:Buffer.alloc(524288)});
  await page.waitForFunction(()=>document.querySelector('[data-save-status]').textContent.includes('No valid'));
  assert.deepEqual(await stored(),latest);
  console.log('File picker, alternate form, PP, actual HP, wrong game, invalid, stale and unchanged snapshot passed');

  await page.locator('#battleTab').click();
  const input=page.locator('#foeInput');
  await input.fill('lucario');
  await page.locator('#foeResults button').filter({hasText:'Lucario'}).first().click();
  await page.locator('#matchups [data-td76-move]').first().waitFor();
  assert.equal(await page.locator('#foePreview').isVisible(),false);
  assert.equal(await page.evaluate(()=>['td681BattleTeam','td76BattleStrip','foeInput','matchups']
   .map(id=>document.getElementById(id).getBoundingClientRect().top).every((y,i,a)=>!i||y>=a[i-1])),true);
  const attack=page.locator('#matchups [data-td76-move]').first();
  await attack.scrollIntoViewIfNeeded();
  const battleScroll=await page.evaluate(()=>scrollY);
  const battleMarkup=await page.locator('#matchups').textContent();
  const matchNode=await page.locator('#matchups .td74-clash').elementHandle();
  await attack.click();
  await page.locator('#td68MoveBack:visible,.td64-move-back:visible').first().click();
  await page.waitForFunction(y=>Math.abs(scrollY-y)<5,battleScroll);
  assert.equal(await page.locator('#matchups').textContent(),battleMarkup);
  assert.equal(await matchNode.evaluate(node=>node.isConnected),true);
  assert.equal(await input.inputValue(),'Lucario');
  console.log('Battle ordering, selected matchup and Move Checker return passed');

  await writeSnapshot(makeSave(21,42,42));
  await picker.setInputFiles(selectedFile);
  await page.waitForFunction(()=>current.pokemon[0].level===42);
  const imported42=await stored();
  assert.equal(await input.inputValue(),'Lucario');
  assert.equal(await page.locator('#battlePage').isVisible(),true);
  assert.equal((await stored()).pokemon[0].saveStats.level,42);
  await page.locator('#moreTab').click();
  await page.locator('#openPlanner').click();
  await page.locator('#planGame').selectOption('Black');
  await page.locator('#planTeam').selectOption(team.id);
  await page.locator('#planMode').selectOption('custom');
  const opp=page.locator('#planOpp details.td63-slot').first();
  await page.locator('#td74EditorOpp > summary').click();
  await opp.locator('summary').first().click();
  const species=opp.locator('input.td66-pokemon-input').first();
  await species.fill('lucario');
  await page.locator('[data-td66-pokemon="lucario"]').click();
  await page.locator('#td74Focus .td74-clash').waitFor();
  await page.locator('#td74Focus [data-td76-move]').first().waitFor();
  assert.equal(await page.locator('#td74Focus .td74-shared-expand').count(),0);
  assert.equal(await page.locator('#td74Focus [data-td76-move]').count(),1);
  const focusedMove=page.locator('#td74Focus [data-td76-move]').first();
  await focusedMove.click();
  await page.locator('#td68MoveBack:visible,.td64-move-back:visible').first().click();
  assert.equal(await page.locator('#plannerPage').isVisible(),true);
  assert.equal(await page.locator('#planMode').inputValue(),'custom');
  await opp.locator('.td74-battle-stats > summary').click();
  const oppSpeed=opp.locator('[data-td74-stat="speed"]');
  const initialSpeed=Number(await oppSpeed.inputValue());
  await oppSpeed.locator('..').locator('[data-td76-stat-step="-1"]').click();
  assert.equal(Number(await oppSpeed.inputValue()),initialSpeed-1);
  assert.equal(await page.locator('#td74EditorOwn').isVisible(),false);
  await page.locator('#teamsTab').click();
  await page.locator('[data-td74-builder-team="v76-test"][data-td74-builder-slot="0"]').click();
  const profile=page.locator('#td77BuilderBattle');
  await profile.locator(':scope > summary').click();
  await profile.locator('.td74-battle-stats > summary').click();
  const speed=profile.locator('[data-td74-stat="speed"]');
  assert.equal(await speed.inputValue(),'88');
  await speed.tap();
  assert.equal(await speed.evaluate(input=>input.selectionEnd-input.selectionStart),2);
  await speed.locator('..').locator('[data-td76-stat-step="1"]').click();
  assert.equal(await speed.inputValue(),'89');
  await profile.locator('#td77BuilderLevel').fill('43');
  await profile.locator('[data-td74-stat="attack"]').fill('199');
  await profile.locator('.td77-builder-equipment > summary').click();
  const chosenAbility=profile.locator('#td2TeamAbility');
  const alternative=await chosenAbility.evaluate(select=>[...select.options].find(option=>option.value&&option.value!==select.value)?.value);
  assert.ok(alternative);
  await chosenAbility.selectOption(alternative);
  await profile.locator('#td77BuilderItem').fill('Life Orb');
  await profile.locator('[data-td74-item-choice="Life Orb"]').click();
  await page.locator('#savePoke').click();
  assert.equal((await stored()).pokemon[0].statAdjustments.speed,1);
  assert.equal((await stored()).pokemon[0].ability,alternative);
  assert.equal((await stored()).pokemon[0].item,'Life Orb');
  assert.equal((await stored()).pokemon[0].level,43);
  assert.equal((await stored()).pokemon[0].saveStats.level,42);
  console.log('6v6 imported stats, expanded attacks, Move Checker return, both steppers and saved stat offsets passed');

  await page.locator('#battleTab').click();
  await input.fill('lucario');
  await page.locator('#foeResults button').filter({hasText:'Lucario'}).first().click();
  await page.locator('#matchups [data-td76-move]').first().waitFor();
  await page.locator('#td76BattleStrip [data-td3-battle-slot="0"]').click();
  assert.match(await page.locator('#matchups .td77-duel-side-own').textContent(),/Life Orb/);
  await picker.setInputFiles(selectedFile);
  await page.waitForFunction(()=>current.pokemon[0].level===42&&!current.pokemon[0].statAdjustments);
  assert.deepEqual((await stored()).pokemon,imported42.pokemon);
  assert.equal(await input.inputValue(),'Lucario');
  assert.doesNotMatch(await page.locator('#matchups .td77-duel-side-own').textContent(),/Life Orb/);
  const matched=await stored();
  // Wait for a completed no-op through the actual picker and verify the matchup node survives.
  await page.locator('[data-save-status]').evaluate(el=>el.textContent='Checking snapshot');
  const unchangedMatch=await page.locator('#matchups .td74-clash').elementHandle();
  await picker.setInputFiles(selectedFile);
  await page.waitForFunction(()=>document.querySelector('[data-save-status]').textContent.startsWith('Saved-game snapshot'));
  assert.deepEqual(await stored(),matched);
  assert.equal(await unchangedMatch.evaluate(el=>el.isConnected),true);
  assert.equal(await picker.inputValue(),'');
  assert.deepEqual(await fs.readFile(selectedFile),makeSave(21,42,42));
  await page.locator('#moreTab').click();
  await page.locator('#openPlanner').click();
  await page.locator('#planTeam').selectOption(team.id);
  await page.waitForFunction(()=>plannerOwn[0].level===42&&plannerOwn[0].saveStats.currentHP===29&&!plannerOwn[0].statAdjustments);
  console.log('Same-path modified and identical save reimports, restored party, Battle and 6v6 updates, and no-op rendering passed');

  await page.locator('#dexTab').click();
  await page.evaluate(()=>takDexBattleNavigationV73.showDex('zigzagoon','dex',{game:'Emerald',id:263}));
  const dexActions=page.locator('#dexResult .td74-dex-actions');
  await dexActions.waitFor();
  const buttons=await dexActions.locator('button').evaluateAll(nodes=>nodes.map(n=>[n.offsetWidth,n.offsetHeight]));
  assert.deepEqual(buttons[0],buttons[1]);
  await page.locator('#dexResult [data-dex-section="learnset"] > summary').click();
  const dexMove=page.locator('#dexResult .td681-learn-row [data-td68-move]').first();
  await dexMove.scrollIntoViewIfNeeded();
  const dexScroll=await page.evaluate(()=>scrollY);
  await dexMove.click();
  await page.locator('#td68MoveBack:visible,.td64-move-back:visible').first().click();
  await page.waitForFunction(y=>Math.abs(scrollY-y)<6,dexScroll);
  await dexActions.locator('[data-td76-species-map]').click();
  assert.equal(await page.locator('#mapsGame').inputValue(),'Emerald');
  await page.waitForFunction(()=>document.querySelectorAll('.td74-encounter-ring').length>1);
  await page.waitForFunction(()=>document.querySelector('#mapsCanvas svg').dataset.selection);
  const fit=async()=>page.evaluate(()=>{
   const bounds=document.getElementById('mapsCanvas').getBoundingClientRect();
   return [...document.querySelectorAll('.td74-encounter-ring')].every(n=>{
    const r=n.getBoundingClientRect();
    return r.left>=bounds.left-1&&r.right<=bounds.right+1&&r.top>=bounds.top-1&&r.bottom<=bounds.bottom+1;
   });
  });
  assert.equal(await fit(),true);
  await page.locator('#mapsFullscreen').click();
  await page.waitForFunction(()=>!document.getElementById('td76FullMapDetails').hidden);
  assert.equal(await fit(),true);
  const transform=()=>page.locator('#td73MapLayer').getAttribute('transform');
  const mapView=await transform(),selection=await page.locator('#mapsCanvas svg').getAttribute('data-selection');
  assert.equal(await page.evaluate(data=>takDexSaveSync.synchronize({teamId:'v76-test',bytes:Uint8Array.from(atob(data),c=>c.charCodeAt(0))}),makeSave(21,44,44).toString('base64')),'updated');
  assert.equal(await transform(),mapView);
  assert.equal(await page.locator('#mapsCanvas svg').getAttribute('data-selection'),selection);
  await page.locator('#td76FullMapDetails > summary').click();
  assert.equal(await page.locator('#td76FullMapDetails #mapsDetails h3').isVisible(),true);
  await page.evaluate(()=>takDexMapsV73.openLocation('Route 101'));
  await page.waitForFunction(()=>document.querySelector('#td76FullMapDetails summary').textContent==='Route 101');
  await page.locator('#mapsClearSelection').click();
  assert.equal(await page.locator('#td76FullMapDetails').isVisible(),false);
  await page.locator('#mapsFullscreen').click();
  await page.locator('#backMaps').click();
  assert.equal(await page.locator('#dexPage').isVisible(),true);
  assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);
  console.log('Pokédex button sizing and move return, Emerald multi-pin framing, fullscreen details, background update and Clear passed');

  await page.evaluate(()=>navigator.serviceWorker.ready);
  await page.waitForFunction(()=>!!navigator.serviceWorker.controller);
  assert.equal(await page.evaluate(()=>[...document.querySelector('#dexGame').options].some(o=>/[🔵🟢]/u.test(o.textContent))),false);
  assert.equal(await page.evaluate(()=>[...document.querySelector('#td59Game').options].some(o=>/⚪/u.test(o.textContent))),true);
  await context.setOffline(true);
  await page.reload({waitUntil:'domcontentloaded'});
  assert.equal(await page.evaluate(()=>typeof takDexSaveSync.synchronize),'function');
  assert.equal((await stored()).pokemon[0].saveStats.level,44);
  assert.equal((await stored()).pokemon[0].level,44);
  assert.equal((await stored()).pokemon[0].statAdjustments,undefined);
  assert.equal(await page.evaluate(async()=>!!(await takDexDB74.api('move/401'))),true);
  assert.equal(await page.evaluate(async()=> (await takDexDB74.encounter('Emerald')).hasSource),true);
  console.log('Offline cold reload, imported party and bundled move/encounter data passed');
  assert.deepEqual(errors,[]);
 } finally {await browser.close();await fs.rm(temp,{recursive:true,force:true});}
})().catch(error=>{console.error(error);process.exitCode=1;});
